@EventBusSubscriber(modid="vandorlabs")
public final class ReaderCanonicalChecks {
 private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {
  int window=700;Actor(ServerLevel level){super(level,new com.mojang.authlib.GameProfile(UUID.fromString("9f8d8656-95e6-43bf-9329-353d822a9300"),"CanonicalReader"));}
  @Override public OptionalInt openMenu(net.minecraft.world.MenuProvider provider,java.util.function.Consumer<net.minecraft.network.RegistryFriendlyByteBuf> writer){containerMenu=provider.createMenu(++window,getInventory(),this);var bytes=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),serverLevel().registryAccess());try{writer.accept(bytes);need(containerMenu instanceof NativeCredentialReaderMenu menu&&bytes.readBlockPos().equals(menu.tile.getBlockPos())&&!bytes.isReadable(),"canonical editor exact position opening buffer");}finally{bytes.release();}return OptionalInt.of(window);}
 }
 private static final String[] IDS={"access_card_slot","data_chip_slot"};
 private static final BlockPos BASE=new BlockPos(8320,110,8320);
 private static int checks,ticks;private static boolean reading;private static BlockPos tracked;
 private static final List<ItemStack> drops=new ArrayList<>();
 private static ResourceLocation id(String name){return ResourceLocation.fromNamespaceAndPath("vandorlabs",name);}
 private static void need(boolean valid,String why){checks++;if(!valid)throw new AssertionError("Canonical reader: "+why);}
 private static NativeCredentialReaderBlock block(int kind){return (NativeCredentialReaderBlock)BuiltInRegistries.BLOCK.get(id(IDS[kind]));}
 private static BlockItem item(int kind){return (BlockItem)BuiltInRegistries.ITEM.get(id(IDS[kind]));}
 private static NativeCredentialReaderEntity owner(ServerLevel level,BlockPos pos){return (NativeCredentialReaderEntity)level.getBlockEntity(pos);}
 private static CompoundTag choices(){var tag=new CompoundTag();tag.putInt("Channel",103);tag.putIntArray("RedstoneChannels",new int[]{103,107});ControlMountSettings.write(new ModernHousingTags(tag),1,2,3);return tag;}
 private static ItemStack configured(int kind){var stack=new ItemStack(item(kind),2);var tag=new CompoundTag();tag.put("RedstoneChannelSettings",choices());stack.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));return stack;}
 private static ItemStack credential(int kind){var stack=kind==0?NativeCredentialItems.accessCard(2):NativeCredentialItems.dataChip(2);if(kind==1){var tag=new CompoundTag();tag.putString("ChipType","journal");tag.putString("JournalTitle","Canonical saved journal");var pages=new ListTag();pages.add(StringTag.valueOf("Canonical reader persists one complete credential."));tag.put("JournalPages",pages);tag.putString("PrivateCanonicalPayload","PRIVATE_CANONICAL");stack.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));}return stack;}
 private static BlockHitResult body(NativeCredentialReaderEntity tile){var p=tile.getBlockPos();var b=tile.getBlockState().getShape(tile.getLevel(),p).bounds();return new BlockHitResult(new Vec3(p.getX()+(b.minX+b.maxX)/2,p.getY()+(b.minY+b.maxY)/2,p.getZ()+(b.minZ+b.maxZ)/2),tile.getBlockState().getValue(NativeMountedSwitchBlock.FACING),p,false);}
 private static NativeCredentialReaderEntity place(ServerLevel level,ServerPlayer actor,BlockPos pos,int kind,Direction face,int yaw){
  level.getChunkAt(pos);for(Direction side:Direction.values())level.setBlock(pos.relative(side),Blocks.AIR.defaultBlockState(),3);level.removeBlock(pos,false);var support=pos.relative(face.getOpposite());level.setBlock(support,Blocks.STONE.defaultBlockState(),3);actor.setGameMode(GameType.SURVIVAL);actor.setShiftKeyDown(false);actor.getInventory().selected=0;actor.setPos(pos.getX()+.5+face.getStepX()*3,pos.getY()+face.getStepY()*3,pos.getZ()+.5+face.getStepZ()*3);actor.setYRot(yaw*90);actor.setXRot(0);var held=configured(kind);actor.setItemInHand(InteractionHand.MAIN_HAND,held);var point=Vec3.atCenterOf(support).add(Vec3.atLowerCornerOf(face.getNormal()).scale(.501));need(held.useOn(new UseOnContext(actor,InteractionHand.MAIN_HAND,new BlockHitResult(point,face,support,false))).consumesAction()&&held.getCount()==1&&level.getBlockState(pos).is(block(kind)),"actual Survival BlockItem placement kind="+kind+" face="+face+" yaw="+yaw);
  var tile=owner(level,pos);need(tile!=null&&tile.getClass()==NativeCredentialReaderEntity.class&&tile.getType()==BuiltInRegistries.BLOCK_ENTITY_TYPE.get(id("token_slot"))&&tile.chip()==(kind==1),"canonical shared factory");int rotation=face.getAxis()==Direction.Axis.Y?(actor.getDirection().get2DDataValue()+(face==Direction.DOWN?2:0))&3:0;need(tile.getBlockState().getValue(NativeMountedSwitchBlock.FACING)==face&&tile.mountRotation()==rotation&&tile.getBlockState().getValue(NativeMountedSwitchBlock.ROTATION)==rotation,"Source orientation metadata");need(tile.mountSettings().height==1&&tile.mountSettings().tilt==2&&tile.mountSettings().direction==3&&tile.getRedstoneChannels().equals(ChannelList.of(103,107))&&!tile.visual().contents().occupied()&&tile.behavior()==0,"item installs choices without physical inventory/policy");return tile;
 }
 private static void registrations(ServerLevel level){
  need(!BuiltInRegistries.BLOCK.containsKey(id("reader_geometry_fixture_card")),"no placeholder readers in canonical focus");for(int kind=0;kind<2;kind++){need(BuiltInRegistries.BLOCK.get(id(IDS[kind])).getClass()==NativeCredentialReaderBlock.class&&item(kind).getBlock()==block(kind),"canonical block/item identity");var state=block(kind).defaultBlockState();need(state.getDestroySpeed(level,BASE)==5&&block(kind).getExplosionResistance()==6&&state.requiresCorrectToolForDrops(),"actual Source5/6 getters");need(new ItemStack(Items.STONE_PICKAXE).isCorrectToolForDrops(state)&&!new ItemStack(Items.WOODEN_PICKAXE).isCorrectToolForDrops(state),"actual stone minimum tags");need(state.getLightEmission()==0&&!state.canBeReplaced(net.minecraft.world.level.material.Fluids.WATER)&&!state.canBeReplaced(net.minecraft.world.level.material.Fluids.LAVA),"static-dark metal replacement policy");need(level.getRecipeManager().byKey(id(IDS[kind])).isEmpty(),"no invented direct reader recipe");for(var possible:block(kind).getStateDefinition().getPossibleStates())need(block(kind).newBlockEntity(BASE,possible).getType()==BuiltInRegistries.BLOCK_ENTITY_TYPE.get(id("token_slot")),"all listed state factories");}
  var tab=BuiltInRegistries.CREATIVE_MODE_TAB.get(id("vandorlabs"));tab.buildContents(new CreativeModeTab.ItemDisplayParameters(level.enabledFeatures(),false,level.registryAccess()));for(int kind=0;kind<2;kind++){final int role=kind;need(tab.getDisplayItems().stream().filter(stack->stack.is(item(role))).count()==1,"one creative item per public kind");}need(BuiltInRegistries.MENU.containsKey(id("token_slot")),"dedicated canonical menu registered");
 }
 private static void edit(ServerLevel level,ServerPlayer actor,NativeCredentialReaderEntity tile){
  actor.setPos(tile.getBlockPos().getX()+.5,tile.getBlockPos().getY(),tile.getBlockPos().getZ()-2);actor.setShiftKeyDown(true);actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);need(actor.gameMode.useItemOn(actor,level,ItemStack.EMPTY,InteractionHand.MAIN_HAND,body(tile)).consumesAction()&&actor.containerMenu instanceof NativeCredentialReaderMenu menu&&menu.tile==tile&&menu.getType()==BuiltInRegistries.MENU.get(id("token_slot")),"survival sneak uses canonical dedicated menu");actor.closeContainer();actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(VandorLabsBootstrap.CONFIGURIZER.get()));need(actor.getMainHandItem().useOn(new UseOnContext(actor,InteractionHand.MAIN_HAND,body(tile))).consumesAction()&&actor.containerMenu instanceof NativeCredentialReaderMenu menu&&menu.tile==tile,"sneaking Configurizer item-use shares configuration path");int window=actor.containerMenu.containerId;need(ReaderSettingsPayload.apply(actor,new ReaderSettingsPayload(window,0,false,4,"103,107",ControlMountSettings.of(1,2,3))),"canonical bounded settings apply");need(!ReaderSettingsPayload.apply(actor,new ReaderSettingsPayload(window+1,0,true,127,"",null)),"stale window refused");actor.closeContainer();actor.setShiftKeyDown(false);
 }
 private static void insert(ServerLevel level,ServerPlayer actor,NativeCredentialReaderEntity tile,int kind){
  actor.setPos(tile.getBlockPos().getX()+.5,tile.getBlockPos().getY(),tile.getBlockPos().getZ()-2);actor.setShiftKeyDown(false);var held=credential(kind).copyWithCount(2);actor.setItemInHand(InteractionHand.MAIN_HAND,held);need(actor.gameMode.useItemOn(actor,level,held,InteractionHand.MAIN_HAND,body(tile)).consumesAction()&&held.getCount()==1&&tile.getItem(0).getCount()==1&&tile.outputLevel()==15,"actual credential insertion consumes one");var pick=block(kind).getCloneItemStack(tile.getBlockState(),body(tile),level,tile.getBlockPos(),actor);tile.saveToItem(pick,level.registryAccess());var data=pick.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();need(pick.is(item(kind))&&data.getCompound("RedstoneChannelSettings").equals(tile.configuration())&&!data.toString().contains("InsertedToken")&&!data.toString().contains("PRIVATE_CANONICAL")&&!pick.has(DataComponents.BLOCK_ENTITY_DATA),"normal/Ctrl pick excludes physical owner");
 }
 @SubscribeEvent public static void joined(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent event){if(tracked!=null&&!event.isCanceled()&&event.getEntity() instanceof ItemEntity item&&item.position().distanceToSqr(Vec3.atCenterOf(tracked))<16)drops.add(item.getItem().copy());}
 private static int dropped(Item item){return drops.stream().filter(stack->stack.is(item)).mapToInt(ItemStack::getCount).sum();}
 private static void mining(ServerLevel level,ServerPlayer actor){int cases=0;for(int kind=0;kind<2;kind++)for(int mode=0;mode<3;mode++)for(boolean opaque:new boolean[]{false,true}){
  var pos=BASE.east(48+kind*8);var tile=place(level,actor,pos,kind,Direction.NORTH,0);insert(level,actor,tile,kind);CompoundTag original=null;if(opaque){original=tile.saveWithoutMetadata(level.registryAccess());var caps=new CompoundTag();caps.putString("future:owned","PRIVATE_CANONICAL_CAPS");original.put("ForgeCaps",caps);tile.loadWithComponents(original,level.registryAccess());need(tile.inert(),"unknown attached owner inert");}actor.setGameMode(mode==2?GameType.CREATIVE:GameType.SURVIVAL);actor.setItemInHand(InteractionHand.MAIN_HAND,mode==0?new ItemStack(Items.STONE_PICKAXE):mode==1?new ItemStack(Items.WOODEN_PICKAXE):ItemStack.EMPTY);tracked=pos;drops.clear();need(actor.gameMode.destroyBlock(pos)&&level.getBlockState(pos).isAir()&&level.getBlockEntity(pos)==null,"actual mining leaves air/no BE");need(dropped(item(kind))==(opaque||mode==0?1:0)&&dropped(kind==0?NativeCredentialItems.ACCESS_CARD.get():NativeCredentialItems.DATA_CHIP.get())==(opaque?0:1),"correct/wrong/creative exact ownership kind="+kind+" mode="+mode+" opaque="+opaque+" drops="+drops);
  if(opaque){final Item expectedItem=item(kind);var recovered=drops.stream().filter(stack->stack.is(expectedItem)).findFirst().orElseThrow();need(recovered.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getCompound("NativeReaderRecovery").equals(original),"sole recovery retains original known+unknown owners");var target=pos.east(3);level.setBlock(target.south(),Blocks.STONE.defaultBlockState(),3);actor.setGameMode(GameType.SURVIVAL);actor.setItemInHand(InteractionHand.MAIN_HAND,recovered.copyWithCount(1));var hit=new BlockHitResult(Vec3.atCenterOf(target.south()).add(0,0,-.501),Direction.NORTH,target.south(),false);need(!actor.getMainHandItem().useOn(new UseOnContext(actor,InteractionHand.MAIN_HAND,hit)).consumesAction()&&actor.getMainHandItem().getCount()==1&&level.getBlockState(target).isAir(),"recovery placement cannot mint reader");}tracked=null;cases++;
 }need(cases==12,"all mining/owner cases");System.out.println("[vandorlabs][reader-canonical] mining PASS cases="+cases);}
 private static void assertSaved(ServerLevel level,BlockPos pos,int kind){var tile=owner(level,pos);need(tile!=null&&!tile.inert()&&tile.chip()==(kind==1)&&tile.getType()==BuiltInRegistries.BLOCK_ENTITY_TYPE.get(id("token_slot"))&&tile.getItem(0).getCount()==1&&tile.outputLevel()==15,"saved sole physical owner");need(tile.getRedstoneChannels().equals(ChannelList.of(103,107))&&tile.mountSettings().height==1&&tile.mountSettings().tilt==2&&tile.mountSettings().direction==3,"saved settings");need(tile.saveWithFullMetadata(level.registryAccess()).getString("id").equals("vandorlabs:token_slot"),"saved released BE identity");need(!tile.getUpdateTag(level.registryAccess()).toString().contains("PRIVATE_CANONICAL"),"public DTO excludes private payload");if(kind==1)need(tile.chipView()!=null&&tile.chipView().journal!=null,"saved chip display metadata prepared");}
 @SubscribeEvent public static void started(ServerStartedEvent event){String phase=System.getProperty("vandorlabs.transmitterPhase","");if(!phase.startsWith("reader-canonical-"))return;var server=event.getServer();try{var level=server.overworld();registrations(level);if(phase.endsWith("read")){for(int kind=0;kind<2;kind++){var pos=BASE.east(kind*8);level.setChunkForced(pos.getX()>>4,pos.getZ()>>4,true);level.getChunkAt(pos);}reading=true;return;}var actor=new Actor(level);actor.setGameMode(GameType.SURVIVAL);int placements=0;for(int kind=0;kind<2;kind++)for(Direction face:Direction.values())for(int yaw=0;yaw<4;yaw++){var pos=BASE.east(100+placements*4);var tile=place(level,actor,pos,kind,face,yaw);tile.takeForDrop();level.removeBlock(pos,false);placements++;}need(placements==48,"all canonical placement orientations");mining(level,actor);for(int kind=0;kind<2;kind++){var tile=place(level,actor,BASE.east(kind*8),kind,Direction.NORTH,0);edit(level,actor,tile);insert(level,actor,tile,kind);NativeRedstoneChannels.flush(level);assertSaved(level,tile.getBlockPos(),kind);}server.saveEverything(true,true,true);System.out.println("[vandorlabs][reader-canonical] write PASS checks="+checks);}catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][reader-canonical] FAIL "+failure);}finally{if(!reading)server.halt(false);}}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.LevelTickEvent.Post event){if(!reading||!(event.getLevel() instanceof ServerLevel level)||level!=level.getServer().overworld())return;try{need(++ticks<400,"restart loaded membership timeout");for(int kind=0;kind<2;kind++){var pos=BASE.east(kind*8);if(!(level.getBlockEntity(pos) instanceof NativeCredentialReaderEntity)||NativeRedstoneChannels.level(level,pos,103)!=15)return;}for(int kind=0;kind<2;kind++)assertSaved(level,BASE.east(kind*8),kind);level.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][reader-canonical] read PASS checks="+checks);reading=false;level.getServer().halt(false);}catch(Throwable failure){failure.printStackTrace();reading=false;System.out.println("[vandorlabs][reader-canonical] FAIL "+failure);level.getServer().halt(false);}}
}
